import {
  View,
  Text,
  TextInput,
  TouchableOpacity,
  useWindowDimensions,
  StyleSheet,
  Image,
  Alert,
  KeyboardAvoidingView,
  Platform,
} from "react-native";
import { useRouter } from "expo-router";
import { useState } from "react";
import { Colors } from "../constants/FormTheme";
import { API_BASE_URL } from "../constants/ApiUrl";
import { CommonStyles } from "../constants/styles";

export default function SignUp() {
  const router = useRouter();
  const [personalNumber, setPersonalNumber] = useState("");
  const [errorMessage, setErrorMessage] = useState("");
  const [loading, setLoading] = useState(false);

  const { width } = useWindowDimensions();
  const isLaptop = width >= 768;

  function showAlert(title: string, message: string) {
    if (typeof window !== "undefined") {
      window.alert(`${title}: ${message}`);
    } else {
      Alert.alert(title, message);
    }
  }

  async function verifyPersonalNumber() {
    if (personalNumber === "") {
      showAlert("Error", "Enter your personal number");
      return;
    }

    setLoading(true);
    try {
      const response = await fetch(
        `${API_BASE_URL}/employees?id=${personalNumber}&action=verify`,
        {
          headers: {
            "ngrok-skip-browser-warning": "true",
          },
        },
      );

      const data = await response.json();
      console.log(data.status);

      if (data.status === "found") {
        const officer = data[personalNumber];
        router.replace({
          pathname: "/VerifyOtpScreen",
          params: {
            personalNumber,
            purpose: "register",
            name: officer.name,
            surname: officer.surname,
            rank: officer.rank,
            station: officer.station,
            caseType: officer.case_type,
            city: officer.city,
          },
        });
      } else if (data.status === "already_registered") {
        setErrorMessage("Account already exists, please log in");
        showAlert("Error", "Account already exists, please log in");
      } else if (data.status === "not found") {
        setErrorMessage(
          "Personal number not recognized. Contact your system administrator.",
        );
        showAlert(
          "Error",
          "Personal number not recognized. Contact your system administrator.",
        );
      } else {
        setErrorMessage("Could not send verification code. Please try again.");
        showAlert(
          "Error",
          "Could not send verification code. Please try again.",
        );
      }
    } catch (error) {
      showAlert("Error", "Something went wrong. Please try again.");
    } finally {
      setLoading(false);
    }
  }

  return (
    <KeyboardAvoidingView
    style={{ flex: 1, backgroundColor: Colors.sapsblue }}
    behavior={Platform.OS === "ios" ? "padding" : "height"}
    keyboardVerticalOffset={0}
  >
    <View style={styles.page}>
      <View
        style={[CommonStyles.cardBase, isLaptop && CommonStyles.cardLaptop]}
      >
        {/* LOGO */}
        <View style={styles.logoWrap}>
          <Image
            source={require("../assets/images/saps-logo.png")}
            style={styles.logoBadge}
            resizeMode="contain"
          />
        </View>

        {/* HEADING */}
        <View style={styles.heading}>
          <Text style={styles.headingTitle}>Sign Up</Text>
          <Text style={styles.headingSubtitle}>
            Verify your personal number to get started
          </Text>
        </View>

        {/* PERSONAL NUMBER */}
        <View style={styles.field}>
          <TextInput
            style={styles.input}
            placeholder="Enter personal number..."
            placeholderTextColor={Colors.grey500}
            value={personalNumber}
            onChangeText={setPersonalNumber}
            autoCapitalize="none"
          />
        </View>

        {/* NOTE */}
        <Text style={styles.note}>
          Enter your SAPS personal number to verify your employment status
          before creating an account.
        </Text>
        {/*Error message*/}
        {errorMessage !== "" && (
          <Text style={styles.footerNote}>{errorMessage}</Text>
        )}
        {/* VERIFY BUTTON */}
        <TouchableOpacity
          style={styles.btnPrimary}
          onPress={verifyPersonalNumber}
          disabled={loading}
        >
          <Text style={styles.btnPrimaryText}>
            {loading ? "Sending code..." : "Verify Personal Number"}
          </Text>
        </TouchableOpacity>

        {/* BACK TO LOGIN */}
        <TouchableOpacity
          style={styles.btnOutline}
          onPress={() => {
            if (router.canDismiss()) {
              router.dismissAll();
            }
            router.replace("/");
          }}
        >
          <Text style={styles.btnOutlineText}>Back to Login</Text>
        </TouchableOpacity>

        {/* FOOTER NOTE */}
        <Text style={styles.footerNote}>
          Only registered SAPS employees can create accounts
        </Text>
      </View>
    </View>
    </KeyboardAvoidingView>
  );
}

const styles = StyleSheet.create({
  page: {
  flexGrow: 1,
  backgroundColor: Colors.sapsblue,
  alignItems: "center",
  justifyContent: "center",
  padding: 24,
  paddingBottom: 48,
},
  logoWrap: {
    alignItems: "center",
    marginBottom: 24,
  },
  logoBadge: {
    width: 110,
    height: 110,
  },
  heading: {
    alignItems: "center",
    marginBottom: 32,
  },
  headingTitle: {
    fontSize: 42,
    fontWeight: "700",
    color: Colors.white,
  },
  headingSubtitle: {
    fontSize: 15,
    color: Colors.grey500,
    marginTop: 6,
    textAlign: "center",
  },
  field: {
    marginBottom: 20,
  },
  input: {
    width: "100%",
    padding: 15,
    paddingLeft: 16,
    backgroundColor: Colors.white,
    borderRadius: 8,
    fontSize: 15,
    color: Colors.sapsblue,
    borderBottomWidth: 3,
    borderBottomColor: Colors.grey500,
  },
  note: {
    textAlign: "center",
    fontSize: 13,
    color: Colors.grey500,
    marginBottom: 28,
    lineHeight: 21,
  },
  btnPrimary: {
    width: "100%",
    padding: 16,
    backgroundColor: Colors.blueMuted,
    borderRadius: 50,
    alignItems: "center",
    marginBottom: 14,
  },
  btnPrimaryText: {
    color: Colors.white,
    fontSize: 20,
    fontWeight: "700",
  },
  btnOutline: {
    width: "100%",
    padding: 15,
    backgroundColor: "transparent",
    borderRadius: 50,
    alignItems: "center",
    borderWidth: 2,
    borderColor: Colors.grey,
    marginBottom: 28,
  },
  btnOutlineText: {
    color: Colors.white,
    fontSize: 20,
    fontWeight: "700",
  },
  footerNote: {
    textAlign: "center",
    fontSize: 12,
    color: Colors.grey500,
  },
});
